fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let t=e.file_type().unwrap();assert!(!t.is_symlink());if t.is_dir(){walk(&e.path(),out);}else{assert!(t.is_file());out.push(e.path());}}}
fn gzip(name:&str,map:&BTreeMap<String,String>){let bytes=serde_json::to_vec(map).unwrap();let p=r(format!("publication-{name}.json"));fs::write(&p,&bytes).unwrap();let c=Command::new("gzip").args(["-n","-c"]).arg(&p).output().unwrap();assert!(c.status.success());let dest=d(format!("artifacts/{name}.json.gz"));fs::write(&dest,c.stdout).unwrap();let c=Command::new("gzip").args(["-d","-c"]).arg(dest).output().unwrap();assert!(c.status.success());assert_eq!(c.stdout,bytes);}
fn stat(v:&Value)->String{format!("{:.6} [{:.6}, {:.6}], {}/15",v["median"].as_f64().unwrap(),v["low"].as_f64().unwrap(),v["high"].as_f64().unwrap(),v["wins"].as_u64().unwrap())}
fn med(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
